    import math

    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(math.sqrt(num)) + 1, 2):
            if num % i == 0:
                return False
        return True

    def fibonacci(n):
        if n <= 0:
            return []
        elif n == 1:
            return [0]
        a, b = 0, 1
        fib_sequence = [0, 1]
        while len(fib_sequence) < n:
            a, b = b, a + b
            fib_sequence.append(b)
        return fib_sequence

    fib_numbers = fibonacci(n)
    for num in fib_numbers:
        if is_prime(num):
            return num

    return None  # In case we reach the limit of generating Fibonacci numbers

