    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    start1, end1 = interval1
    start2, end2 = interval2

    if start1 <= end2 and end1 >= start2:
        intersection_length = min(end1, end2) - max(start1, start2)
        if is_prime(intersection_length):
            return "YES"
        else:
            return "NO"
    else:
        return "NO"

# Test cases
print(intersection((1, 2), (2, 3)))  # "NO"
print(intersection((-1, 1), (0, 4)))  # "NO"
print(intersection((-3, -1), (-5, 5)))  # "YES"
```

This solution includes a helper function `is_prime(n)` to check if a number is prime. The main function `intersection(interval1, interval2)` calculates the intersection of two intervals and checks if the length of the intersection is a prime number. If the intervals do not intersect, it returns "NO".

