def file_name_check(file_name):
    import re

    def has_valid_digits(name):
        return re.search(r'\d{1,3}', name) is not None

    def has_valid_extension(name):
        return name.split('.')[-1] in ['txt', 'exe', 'dll']

    def starts_with_letter(name):
        return name.split('.')[0][0].isalpha()

    def is_valid_name(name):
        parts = name.split('.')
        return (has_valid_digits(name) and
                len(parts) == 2 and
                parts[0] and
                starts_with_letter(name) and
                has_valid_extension(name))

    return 'Yes' if is_valid_name(file_name) else 'No'
```

